export function getLoCharacter(slug) {
  return loCharacters.find((c) => c.slug === slug);
}

export const LO_ROLES = ['Attacker', 'Defender', 'Supporter'];
export const LO_ARMOR_TYPES = ['Light', 'Heavy', 'Air'];
export const LO_RANKS = ['B', 'A', 'S', 'SS'];
export const LO_FACTIONS = [...new Set(loCharacters.map((c) => c.faction).filter(Boolean))].sort();
